30	const TransactionListAmountRangeFilter: React.FC<TransactionListAmountRangeFilterProps> = ({
31	  filterAmountRange,
32	  amountRangeFilters,
33	  resetAmountRange,
34	}) => {
35	  const theme = useTheme();
36	  const xsBreakpoint = useMediaQuery(theme.breakpoints.only("xs"));
37	
38	  const initialAmountRange = [0, 100];
39	  const [amountRangeValue, setAmountRangeValue] = React.useState<number[]>(initialAmountRange);
40	
41	  const [amountRangeAnchorEl, setAmountRangeAnchorEl] = React.useState<HTMLDivElement | null>(null);
42	
43	  const handleAmountRangeClick = (event: React.MouseEvent<HTMLDivElement>) => {
44	    setAmountRangeAnchorEl(event.currentTarget);
45	  };
46	
