52	    filterAmountRange({
53	      amountMin: padAmountWithZeros(first(amountRange as number[]) as number),
54	      amountMax: padAmountWithZeros(last(amountRange as number[]) as number),
55	    });
56	    setAmountRangeValue(amountRange as number[]);
57	  };
58	
59	  const amountRangeOpen = Boolean(amountRangeAnchorEl);
