91	              }}
92	            >
93	              Clear
94	            </Button>
95	          </Grid>
96	        </Grid>
97	      </Grid>
98	      <Grid item>
99	        <Slider
100	          data-test="transaction-list-filter-amount-range-slider"
101	          sx={{ width: "200px" }}
102	          value={amountRangeValue}
103	          min={0}
104	          max={100}
