130	          anchorEl={amountRangeAnchorEl}
131	          onClose={handleAmountRangeClose}
132	          anchorOrigin={{
133	            vertical: "bottom",
134	            horizontal: "left",
135	          }}
136	          transformOrigin={{
137	            vertical: "top",
138	            horizontal: "left",
139	          }}
140	        >
141	          <AmountRangeFilter />
142	        </Popover>
143	      )}
144	      {xsBreakpoint && (
145	        <Drawer
146	          id={amountRangeId}
147	          open={amountRangeOpen}
148	          ModalProps={{ onClose: handleAmountRangeClose }}
149	          anchor="bottom"
150	          data-test="amount-range-filter-drawer"
151	        >
