import React from "react";
import { Box, Typography, Grid, colors } from "@mui/material";

const { grey } = colors;

const EmptyList: React.FC<{ entity: string; children?: React.ReactNode }> = ({
  entity,
  children,
}) => {
  return (
    <Box
      display="flex"
