const { chromium } = require('/Users/stephenhe/Projects/capybara-benchmark/projects/cypress-realworld-app/node_modules/playwright-core');

async function setupApiProxy(page) {
  await page.route(/localhost:3001/, async (route) => {
    const url = route.request().url().replace('localhost:3001', 'localhost:3003');
    try { const response = await route.fetch({ url }); await route.fulfill({ response }); }
    catch (e) { await route.abort().catch(() => {}); }
  });
}

async function run() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const results = [];

  await setupApiProxy(page);

  // Login as Heath93
  await page.goto('http://localhost:3000/signin');
  await page.locator('[data-test=signin-username] input').fill('Heath93');
  await page.locator('[data-test=signin-password] input').fill('s3cret');
  await page.click('[data-test=signin-submit]');
  await page.waitForSelector('[data-test=sidenav]', { timeout: 15000 });

  // 1. Verify pending request transaction detail
  await page.goto('http://localhost:3000/transaction/demK0p0GCvG');
  await page.waitForSelector('[data-test=transaction-detail-header]', { timeout: 10000 });
  const pendingChecks = {
    'transaction-detail-header': await page.locator('[data-test=transaction-detail-header]').count() > 0,
    'accept-request': await page.locator('[data-test^=transaction-accept-request-]').count() > 0,
    'reject-request': await page.locator('[data-test^=transaction-reject-request-]').count() > 0,
    'url': page.url()
  };
  results.push({ page: '/transaction/:id#pending-request', status: 'OK', checks: pendingChecks });

  // 2. Complete a transaction flow (step 3)
  await page.click('[data-test=nav-top-new-transaction]');
  await page.waitForURL('**/transaction/new', { timeout: 5000 });
  await page.waitForSelector('[data-test^=user-list-item-]', { timeout: 5000 });
  // Click first user
  await page.locator('[data-test^=user-list-item-]').first().click();
  await page.waitForSelector('[data-test=transaction-create-amount-input]', { timeout: 5000 });
  // Fill amount and description
  await page.locator('[data-test=transaction-create-amount-input] input').fill('10');
  await page.locator('[data-test=transaction-create-description-input]').fill('Test transaction');
  await page.waitForTimeout(500);
  // Click Pay button  
  await page.click('[data-test=transaction-create-submit-payment]');
  await page.waitForSelector('[data-test=new-transaction-return-to-transactions]', { timeout: 10000 });
  const step3Checks = {
    'return-to-transactions': await page.locator('[data-test=new-transaction-return-to-transactions]').count() > 0,
    'create-another': await page.locator('[data-test=new-transaction-create-another-transaction]').count() > 0,
    'url': page.url()
  };
  results.push({ page: '/transaction/new#step-3', status: 'OK', checks: step3Checks });

  // 3. Onboarding - create a new user to verify onboarding dialog
  // Register a new user
  await page.goto('http://localhost:3000/signup');
  await page.waitForSelector('[data-test=signup-first-name]', { timeout: 5000 });
  await page.locator('[data-test=signup-first-name] input').fill('Test');
  await page.locator('[data-test=signup-last-name] input').fill('User');
  await page.locator('[data-test=signup-username] input').fill('testuser_' + Date.now());
  await page.locator('[data-test=signup-password] input').fill('s3cret');
  await page.locator('[data-test=signup-confirmPassword] input').fill('s3cret');
  await page.click('[data-test=signup-submit]');
  // Wait for onboarding dialog
  await page.waitForSelector('[data-test=user-onboarding-dialog]', { timeout: 10000 });
  const onboardingChecks = {
    'user-onboarding-dialog': await page.locator('[data-test=user-onboarding-dialog]').count() > 0,
    'user-onboarding-dialog-title': await page.locator('[data-test=user-onboarding-dialog-title]').innerText(),
    'user-onboarding-next': await page.locator('[data-test=user-onboarding-next]').count() > 0,
    'user-onboarding-logout': await page.locator('[data-test=user-onboarding-logout]').count() > 0,
    'url': page.url()
  };
  results.push({ page: '/#onboarding-step-1', status: 'OK', checks: onboardingChecks });

  // Click Next to go to step 2
  await page.click('[data-test=user-onboarding-next]');
  await page.waitForSelector('[data-test=bankaccount-bankName-input]', { timeout: 5000 });
  const onb2Checks = {
    'bankaccount-form': await page.locator('[data-test=bankaccount-form]').count() > 0,
    'bankaccount-bankName-input': await page.locator('[data-test=bankaccount-bankName-input]').count() > 0,
    'user-onboarding-dialog-title': await page.locator('[data-test=user-onboarding-dialog-title]').innerText(),
    'url': page.url()
  };
  results.push({ page: '/#onboarding-step-2', status: 'OK', checks: onb2Checks });

  // Fill bank account form and submit
  await page.locator('[data-test=bankaccount-bankName-input] input').fill('Test Bank');
  await page.locator('[data-test=bankaccount-routingNumber-input] input').fill('123456789');
  await page.locator('[data-test=bankaccount-accountNumber-input] input').fill('123456789');
  await page.click('[data-test=bankaccount-submit]');
  await page.waitForTimeout(2000);
  const onb3Checks = {
    'user-onboarding-dialog': await page.locator('[data-test=user-onboarding-dialog]').count() > 0,
    'user-onboarding-dialog-title': await page.locator('[data-test=user-onboarding-dialog-title]').innerText().catch(() => 'n/a'),
    'user-onboarding-next': await page.locator('[data-test=user-onboarding-next]').count() > 0,
    'url': page.url()
  };
  results.push({ page: '/#onboarding-step-3', status: 'OK', checks: onb3Checks });

  console.log(JSON.stringify(results, null, 2));
  await browser.close();
}

