  const dialogVisible = await p2.locator('[data-test=user-onboarding-dialog]').isVisible().catch(() => false);
  const pageUrl = p2.url();
  const title = dialogVisible ? await p2.locator('[data-test=user-onboarding-dialog-title]').innerText().catch(() => 'err') : 'n/a';
  results.push({ page: '/#onboarding (new user login)', status: dialogVisible ? 'OK' : 'NOT_VISIBLE', url: pageUrl, checks: {
    'dialog-visible': dialogVisible,
    'title': title
  }});

  if (dialogVisible) {
    // Step 2
    await p2.click('[data-test=user-onboarding-next]');
    await p2.waitForSelector('[data-test=bankaccount-bankName-input]', { timeout: 5000 });
    const title2 = await p2.locator('[data-test=user-onboarding-dialog-title]').innerText().catch(() => 'err');
    results.push({ page: '/#onboarding-step-2', status: 'OK', title2 });

    // Fill form
    await p2.locator('[data-test=bankaccount-bankName-input] input').fill('Test Bank Name');
    await p2.locator('[data-test=bankaccount-routingNumber-input] input').fill('123456789');
    await p2.locator('[data-test=bankaccount-accountNumber-input] input').fill('123456789');
    await p2.click('[data-test=bankaccount-submit]');
    await p2.waitForTimeout(3000);
    const still = await p2.locator('[data-test=user-onboarding-dialog]').isVisible().catch(() => false);
    const title3 = still ? await p2.locator('[data-test=user-onboarding-dialog-title]').innerText().catch(() => 'err') : 'closed';
    results.push({ page: '/#onboarding-step-3', status: still ? 'OK' : 'NOT_VISIBLE', title3 });
  }
  await ctx2.close();

  console.log(JSON.stringify(results, null, 2));
  await browser.close();
}

run().catch(e => { console.error('ERROR:', e.message, e.stack); process.exit(1); });
